def main():
    root = os.getcwd()
    base = os.path.join(root, MOD)
    if not os.path.isdir(base):
        sys.exit(f'not at the repo root: {base} missing')
    results, misses = {}, []
    for rel, hunks in HUNKS.items():
        p = os.path.join(base, rel)
        with open(p, encoding='utf-8', newline='') as f: raw = f.read()
        crlf = '\r\n' in raw
        s = raw.replace('\r\n', '\n')
        applied = skipped = 0
        for i, (old, new) in enumerate(hunks):
            if new and s.count(new) == 1 and (old not in new or s.count(old) == 1) and (old in new or s.count(old) == 0):
                skipped += 1
            elif s.count(old) == 1:
                s = s.replace(old, new, 1); applied += 1
            else:
                misses.append(f'{rel} hunk {i + 1}: old x{s.count(old)}, new x{s.count(new) if new else 0}')
        results[rel] = (p, raw, s.replace('\n', '\r\n') if crlf else s, applied, skipped, raw.count('\n'), s.count('\n'))
    if misses:
        print('apply-1.12.0: nothing written; these hunks do not match:')
        for m in misses: print('  ' + m)
        sys.exit(1)
    for rel, (p, raw, out, applied, skipped, before, after) in results.items():
        if out != raw:
            with open(p, 'w', encoding='utf-8', newline='') as f: f.write(out)
        print(f'{rel:30} {applied:3} applied {skipped:3} already  lines {before} -> {after}')

if __name__ == '__main__':
    main()
